/**
 * INVARIANT: the authorisation table is DEFAULT DENY, complete, and reached.
 *
 * MECHANISM: RUNTIME REGISTRY, plus one compile-time claim about the keys.
 *
 * Every walk here asks the built Fastify application what it registered, after all twelve
 * route modules have run. Nothing compares two hand-maintained tables: earlier releases'
 * route inventory was a JSON fixture regenerated by hand, which is a second copy that
 * can drift with the first, and its catch-all test compared a fixture row rather than
 * asking what the server does with an unrouted path.
 *
 * The method half is checked against the built table: every `ROUTE_ROLES` key names an HTTP
 * method or `WS`, and `WS` names the log stream and nothing else.
 */
import Fastify from 'fastify';

import { createApp } from '../../../src/web/app';
import {
  ROUTE_ROLES,
  installRouteCompleteness,
  routeRequirement,
  toBraceRouteKey,
  type RegisteredRoute,
} from '../../../src/web/route-table';
import * as routes from '../../../src/web/routes/index';

async function registeredRoutes(): Promise<RegisteredRoute[]> {
  const probe = Fastify();
  const captured = installRouteCompleteness(probe);
  routes.registerAll(probe);
  await probe.ready();
  await probe.close();
  return captured;
}

describe('the default-deny route table against the real registry', () => {
  it('has a minimum role for every API route the twelve modules register', async () => {
    const registered = await registeredRoutes();
    const missing: string[] = [];
    let checked = 0;
    for (const route of registered) {
      const spa = route.config.houstonSpa === true;
      if (spa) continue;
      if (!(route.url.startsWith('/api/') || route.url === '/signin' || route.url === '/signout')) {
        continue;
      }
      if (route.method === 'OPTIONS') continue;
      if (route.method === 'HEAD' && route.generatedHead === true) continue;
      const method = route.config.houstonTransport === 'WS' ? 'WS' : route.method;
      if (method === 'HEAD') continue;
      checked += 1;
      if (routeRequirement(method, route.url) === null) missing.push(`${method} ${route.url}`);
    }
    // A walk that found no routes would pass vacuously, which is how earlier releases'
    // version of this guard would have degraded after the handlers moved.
    expect(checked).toBeGreaterThan(40);
    expect(missing).toEqual([]);
  });

  it('lists nothing the application does not register', async () => {
    const registered = await registeredRoutes();
    const live = new Set<string>();
    for (const route of registered) {
      if (route.config.houstonSpa === true) continue;
      if (route.method === 'HEAD' && route.generatedHead === true) continue;
      const method = route.config.houstonTransport === 'WS' ? 'WS' : route.method;
      const [translated, template] = toBraceRouteKey([method, route.url]);
      live.add(`${translated} ${template}`);
    }
    // DEFAULT DENY makes a missing row a runtime refusal, which `installRouteCompleteness`
    // already turns into a failed boot. The other direction is the silent one: a row for a
    // route nothing serves is a permission granted to nothing, and the next reader reads
    // it as a live grant.
    const stale = [...ROUTE_ROLES.keys()].filter((row) => !live.has(row));
    expect(stale).toEqual([]);
  });

  it('uses WS for exactly the log stream and nothing else', () => {
    // Walked on the built table rather than typed as a template-literal key, so the claim is
    // made against the same object every request is authorised from.
    const wsRows = [...ROUTE_ROLES.keys()].filter((row) => row.startsWith('WS '));
    expect(wsRows).toEqual(['WS /api/repros/{name}/logs/stream']);
    for (const row of ROUTE_ROLES.keys()) {
      const method = row.slice(0, row.indexOf(' '));
      expect(['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS', 'WS']).toContain(method);
    }
  });

  it('registers exactly the twelve modules, each with one entry point', () => {
    const names = Object.keys(routes).filter((name) => name !== 'registerAll');
    expect(names).toEqual([]);
    expect(typeof routes.registerAll).toBe('function');
    // The modules themselves: one `register` each, and no second entry point beside it.
    for (const name of [
      'backup',
      'clusters',
      'data',
      'edge',
      'jobs',
      'logs',
      'meta',
      'people',
      'perf',
      'repros',
      'session',
      'spa',
    ]) {
      const module = require(`../../../src/web/routes/${name}`) as Record<string, unknown>;
      // A REGISTRAR each. Earlier releases asserted each module exports only `register`;
      // TypeScript has no export list to read, and two of these modules legitimately export a helper a sibling or
      // their own spec uses. The checkable form of "one entry point" is therefore the
      // import DIRECTION -- nothing outside the package may reach past `register` -- and
      // `source-rules.test.ts` owns that as a ts-morph walk.
      expect(typeof module.register).toBe('function');
    }
  });

  it('never serves an API path the single-page application', async () => {
    const app = await createApp({ accounts: false });
    try {
      await app.ready();
      const health = await app.inject({ method: 'GET', url: '/api/health' });
      expect(health.statusCode).toBe(200);
      expect(health.json()).toMatchObject({ ok: true });

      // The catch-all's failure mode is a 200 with the wrong body, so this asserts the
      // body rather than the position of a fixture row.
      const unknown = await app.inject({ method: 'GET', url: '/api/nothing-here' });
      expect(unknown.statusCode).toBe(404);
      expect(String(unknown.headers['content-type'])).toContain('application/json');

      // And the application shell is still served where it should be. `/` is the SPA;
      // an unknown browser path is a JSON 404, exactly as earlier releases' front door answers,
      // so the catch-all cannot be hiding a wrong-body 200 anywhere.
      const shell = await app.inject({ method: 'GET', url: '/' });
      expect(shell.statusCode).toBe(200);
      expect(String(shell.headers['content-type'])).toContain('text/html');
      const stray = await app.inject({ method: 'GET', url: '/not-a-real-spa-route' });
      expect(stray.statusCode).toBe(404);
      expect(String(stray.headers['content-type'])).toContain('application/json');
    } finally {
      await app.close();
    }
  });
});
